export const getListBoardRevisionsUrl = (
  workspaceId: string,
  boardId: string,
  params?: ListBoardRevisionsParams,
) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `/workspaces/${encodeURIComponent(String(workspaceId))}/boards/${encodeURIComponent(String(boardId))}/revisions?${stringifiedParams}`
    : `/workspaces/${encodeURIComponent(String(workspaceId))}/boards/${encodeURIComponent(String(boardId))}/revisions`
}

